@Test
public void testContextClassLoader_3_oe() throws Exception {

    final ClassLoader savedClassloader = Thread.currentThread().getContextClassLoader();

    try (final CustomClassLoader cl1 = new CustomClassLoader(1)) {
        Thread.currentThread().setContextClassLoader(cl1);
        final CustomClassLoaderObjectFactory factory1 = new CustomClassLoaderObjectFactory(1);
        try (final GenericObjectPool<URL> pool1 = new GenericObjectPool<>(factory1)) {
            pool1.setMinIdle(1);
            pool1.setTimeBetweenEvictionRuns(Duration.ofMillis(100));
            int counter = 0;
            while (counter < 50 && pool1.getNumIdle() != 1) {
                Thread.sleep(100);
                counter++;
            }
            // removed other assertion

            try (final CustomClassLoader cl2 = new CustomClassLoader(2)) {
                Thread.currentThread().setContextClassLoader(cl2);
                final CustomClassLoaderObjectFactory factory2 = new CustomClassLoaderObjectFactory(2);
                try (final GenericObjectPool<URL> pool2 = new GenericObjectPool<>(factory2)) {
                    pool2.setMinIdle(1);

                    pool2.addObject();
                    // removed other assertion
                    pool2.clear();

                    pool2.setTimeBetweenEvictionRuns(Duration.ofMillis(100));

                    counter = 0;
                    while (counter < 50 && pool2.getNumIdle() != 1) {
                        Thread.sleep(100);
                        counter++;
                    }
                    assertEquals(1, pool2.getNumIdle(), "Wrong number of  idle objects in pool2");
}
}
}
}
}

@Test
public void testGetLastBorrowTrace_1_oe() throws Exception {
    final AbandonedConfig abandonedConfig = new AbandonedConfig();

    abandonedConfig.setRemoveAbandonedOnBorrow(true);
    abandonedConfig.setRemoveAbandonedTimeout(TestConstants.ONE_SECOND_DURATION);
    abandonedConfig.setLogAbandoned(true);
    try (final GenericObjectPool<String> pool = new GenericObjectPool<>(new SimpleFactory(),
            new GenericObjectPoolConfig<>(), abandonedConfig)) {

        pool.borrowObject();
        // pool.returnObject(s1); // Object not returned, causes abandoned object created exception

        final Set<DefaultPooledObjectInfo> strings = pool.listAllObjects();
        final DefaultPooledObjectInfo s1Info = strings.iterator().next();
        final String lastBorrowTrace = s1Info.getLastBorrowTrace();

        assertTrue(lastBorrowTrace.startsWith("Pooled object created"));
}
}

