@Test
public void testWhenExhaustedBlock_1_oe() throws Exception {
    abandonedConfig.setRemoveAbandonedOnMaintenance(true);
    pool.setAbandonedConfig(abandonedConfig);
    pool.setTimeBetweenEvictionRuns(Duration.ofMillis(500));

    pool.setMaxTotal(1);

    @SuppressWarnings("unused") // This is going to be abandoned
    final PooledTestObject o1 = pool.borrowObject(0);

    final long startMillis = System.currentTimeMillis();
    final PooledTestObject o2 = pool.borrowObject(0, 5000);
    final long endMillis = System.currentTimeMillis();

    pool.returnObject(0, o2);

    assertTrue(endMillis - startMillis < 5000);
}

@ParameterizedTest
@MethodSource("data")
public void testPrintClearedStackTraceIsNoOp_1_oe(final CallStack stack) {
    stack.fillInStackTrace();
    stack.clear();
    stack.printStackTrace(new PrintWriter(writer));
    final String stackTrace = writer.toString();
    assertEquals("", stackTrace);
}

@ParameterizedTest
@MethodSource("data")
public void testPrintFilledStackTrace_1_oe(final CallStack stack) {
    stack.fillInStackTrace();
    stack.printStackTrace(new PrintWriter(writer));
    final String stackTrace = writer.toString();
    assertTrue(stackTrace.contains(getClass().getName()));
}
